   var table=new DataGrid{Name="zapretProfileGrid",ItemsSource=session.State.ZapretProfiles};selectedProfile=session.State.ZapretProfiles.FirstOrDefault(p=>selectedProfile!=null&&p.Id==selectedProfile.Id)??session.State.ZapretProfiles.FirstOrDefault();table.SelectedItem=selectedProfile;table.SelectionChanged+=(s,e)=>selectedProfile=table.SelectedItem as ZapretProfile;
   table.Columns.Add(CellColumn("Профиль / выход",1.15,o=>{var p=(ZapretProfile)o;var name=new TextBox{Text=p.Name,Background=Brush("#101D283F"),BorderBrush=Brush("#405C7090"),Margin=new Thickness(0),Padding=new Thickness(8,4,8,4),ToolTip="Название профиля · можно редактировать"};name.LostKeyboardFocus+=async(s,e)=>{string next=name.Text.Trim();if(next.Length==0){name.Text=p.Name;return;}if(next!=p.Name)await Run(()=>session.ChangeConfiguration(()=>p.Name=next));};return name;}));var strategies=new Dictionary<string,ZapretStrategy>();var options=new List<Choice>{new Choice{Key="",Label="Выберу позже"}};
