  async void LoadProfileCatalog(DataGrid table,List<Choice> options,Dictionary<string,ZapretStrategy> strategies){try{var catalog=await session.Strategies();await Dispatcher.InvokeAsync(()=>{},System.Windows.Threading.DispatcherPriority.Loaded);if(closing||current!="Zapret & Byetube"||engineInterface!="Zapret"||!table.IsLoaded)return;foreach(var s in catalog){options.Add(new Choice{Key=s.Id,Label=s.ShortName});strategies[s.Id]=s;}table.Items.Refresh();}catch(Exception ex){if(!closing&&table.IsLoaded)status.Text=ex.Message;}}
  async Task EditZapretProfile(ZapretProfile profile){
   EnsureEditable();var catalog=await session.Strategies();var dialog=Dialog(profile==null?"Новый профиль":"Изменить профиль",780,420);dialog.MaxHeight=dialog.Height;dialog.SizeToContent=SizeToContent.Height;var panel=new StackPanel{Margin=new Thickness(20)};
   panel.Children.Add(Text("Название профиля"));var name=new TextBox{Name="zapretEditorName",Text=profile==null?"Новый профиль":profile.Name};panel.Children.Add(name);panel.Children.Add(Text("Стратегия"));var strategy=new ComboBox{Name="zapretEditorStrategy",ItemsSource=catalog,DisplayMemberPath="ShortName",SelectedItem=profile==null?catalog.FirstOrDefault():catalog.FirstOrDefault(s=>s.Id==profile.Settings.Strategy),IsEnabled=catalog.Length>0};panel.Children.Add(strategy);
   var feedback=Text(catalog.Length==0?"Нет доступных стратегий. Обновите каталог движка Zapret.":"");feedback.Name="zapretEditorFeedback";feedback.Visibility=catalog.Length==0?Visibility.Visible:Visibility.Collapsed;feedback.Margin=new Thickness(0,8,0,8);panel.Children.Add(feedback);
   var save=Button("Сохранить",()=>{if(String.IsNullOrWhiteSpace(name.Text)||strategy.SelectedItem==null){feedback.Text="Введите название и выберите стратегию.";feedback.Visibility=Visibility.Visible;return;}dialog.DialogResult=true;});save.Name="zapretEditorSave";save.IsEnabled=catalog.Length>0;var cancel=Button("Отмена",()=>dialog.DialogResult=false);panel.Children.Add(Toolbar(save,cancel));dialog.Content=panel;if(dialog.ShowDialog()!=true)return;
   var selected=(ZapretStrategy)strategy.SelectedItem;var p=profile??new ZapretProfile{Enabled=false};await session.ChangeConfiguration(()=>{p.Name=name.Text.Trim();p.Settings.Strategy=selected.Id;p.Settings.Family=selected.Family;if(profile==null)session.State.ZapretProfiles.Add(p);});selectedProfile=p;RegisterHotkeys();RefreshAfterOperation("Zapret");
  }
  async Task AssignProfileLists(ZapretProfile profile){EnsureEditable();selectedProfile=profile;var available=await Task.Run(()=>RoutePresets.Groups.Where(p=>!p.OutsideRussia).ToArray());var dialog=Dialog("Пресеты · "+profile.Name,860,620);var panel=new DockPanel{Margin=new Thickness(24)};var list=new StackPanel();var entries=new List<Tuple<CheckBox,RouteList,RoutePreset>>();foreach(var route in session.State.Lists){var check=new CheckBox{Style=(Style)FindResource("LabeledPacketCheck"),Margin=new Thickness(0,0,0,8),Content=(route.PresetNames!=null&&route.PresetNames.Count>0?"Пресет · ":"Список · ")+route.Name,Foreground=Brush(route.Name.Contains("Популярные сервисы")?"#FFDD74":"#F0F8FF"),IsChecked=route.Target=="zapret"&&route.ZapretProfileId==profile.Id,IsEnabled=route.Target!="zapret"||String.IsNullOrEmpty(route.ZapretProfileId)||route.ZapretProfileId==profile.Id};list.Children.Add(check);entries.Add(Tuple.Create(check,route,(RoutePreset)null));}foreach(var preset in available.Where(p=>!session.State.Lists.Any(r=>r.Target=="zapret"&&r.ZapretProfileId==profile.Id&&(r.PresetNames??new List<string>()).Contains(p.Name)))){var check=new CheckBox{Style=(Style)FindResource("LabeledPacketCheck"),Margin=new Thickness(0,0,0,8),Content="Пресет · "+preset.DisplayName,Foreground=Brush(preset.Name.Contains("Популярные сервисы")?"#FFDD74":"#F0F8FF")};list.Children.Add(check);entries.Add(Tuple.Create(check,(RouteList)null,preset));}var actions=Toolbar(Button("Сохранить",()=>dialog.DialogResult=true),Button("Отмена",()=>dialog.DialogResult=false));DockPanel.SetDock(actions,Dock.Bottom);panel.Children.Add(actions);panel.Children.Add(new ScrollViewer{Content=list,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});dialog.Content=panel;if(dialog.ShowDialog()!=true)return;var added=new List<RouteList>();foreach(var item in entries.Where(i=>i.Item1.IsChecked==true&&i.Item3!=null)){var preset=item.Item3;string presetText=await PresetStorage.Load(session.Core,preset);added.Add(new RouteList{Name=preset.Name,Text=presetText,PresetEntries=new Dictionary<string,string>{{preset.Name,presetText}},SourceUrls=PresetStorage.Sources(preset).ToList(),PresetNames=new List<string>{preset.Name},Target="zapret",ZapretProfileId=profile.Id,MatchMode="addresses"});}await session.ChangeConfiguration(()=>{foreach(var item in entries.Where(i=>i.Item2!=null)){var route=item.Item2;if(item.Item1.IsChecked==true){route.Target="zapret";route.ZapretProfileId=profile.Id;}else if(route.Target=="zapret"&&route.ZapretProfileId==profile.Id){route.Target="direct";route.ZapretProfileId=null;}}session.State.Lists.AddRange(added);if(!session.State.Lists.Any(r=>r.Target=="zapret"&&r.ZapretProfileId==profile.Id))profile.Enabled=false;});RefreshAfterOperation("Zapret");}
  UIElement ByeTubeWorkspace(){
   var panel=new StackPanel();panel.Children.Add(Text("ByeTube",16));panel.Children.Add(Text("Резервный способ обхода YouTube, если Zapret не помог.",12));var variants=ByeTube.Strategies;int savedIndex=Array.IndexOf(variants,session.State.ByeTubeStrategy);var picker=new ComboBox{Name="byeTubeStrategy",ItemsSource=variants.Select((s,i)=>"Стратегия "+(i+1)+" · "+s).ToArray(),SelectedIndex=Math.Max(0,savedIndex)};panel.Children.Add(picker);panel.Children.Add(Text("Локальный обход через ByeDPI, не VPN. Стратегия применяется только назначенным маршрутам."));
   var feedback=Text(savedIndex<0&&!String.IsNullOrEmpty(session.State.ByeTubeStrategy)?"Сохранённая стратегия недоступна. Выберите и сохраните новую.":"",12);feedback.Name="byeTubeFeedback";feedback.Visibility=feedback.Text.Length==0?Visibility.Collapsed:Visibility.Visible;panel.Children.Add(feedback);
   var save=Button("Сохранить стратегию",async()=>{if(picker.SelectedIndex<0){feedback.Text="Выберите стратегию ByeTube.";feedback.Visibility=Visibility.Visible;return;}await Run(async()=>{await session.ChangeConfiguration(()=>session.State.ByeTubeStrategy=variants[picker.SelectedIndex]);feedback.Text="Стратегия ByeTube сохранена.";feedback.Visibility=Visibility.Visible;RecordEvent(feedback.Text);});});save.Name="byeTubeSave";
   var toggle=AsyncButton("Включить / выключить ByeTube",async()=>{if(picker.SelectedIndex<0)throw new InvalidOperationException("Выберите стратегию ByeTube.");await session.ChangeConfiguration(()=>session.State.ByeTubeStrategy=variants[picker.SelectedIndex]);await session.ToggleRoutedOutput(false,true);});toggle.Name="byeTubeToggle";
   panel.Children.Add(Toolbar(save,toggle,Button("Назначить сервисы",()=>Page("Маршрутизация"))));panel.Children.Add(Text("Подбор и проверка стратегий доступны в мастере настройки."));panel.Children.Add(Button("Открыть мастер",()=>Page("Мастер настройки")));panel.Margin=new Thickness(0,12,0,0);picker.Margin=new Thickness(0,8,0,14);return new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};
